    const a=normalize(expected).split(' ').filter(Boolean),b=normalize(heard).split(' ').filter(Boolean);
    const rows=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
    for(let i=0;i<=a.length;i++)rows[i][0]=i;
    for(let j=0;j<=b.length;j++)rows[0][j]=j;
    for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)rows[i][j]=Math.min(rows[i-1][j]+1,rows[i][j-1]+1,rows[i-1][j-1]+(a[i-1]===b[j-1]?0:1));
    return {score:Math.max(0,Math.round((1-rows[a.length][b.length]/Math.max(a.length,b.length,1))*100)),exact:normalize(expected)===normalize(heard),words:a.map(word=>({word,found:b.includes(word)}))};
