    return header(book.title,`27 小课 · ${book.sentences.length} 个练习句 · 已掌握 ${progress(book)} 句`,`<button class="button" data-route="textbooks">返回教材</button>`)+`<div class="textbook-banner"><div><h2>听、说、读、写，一步一步来。</h2><p>点击任意小课选择练习模式。键盘音、答题提示音和语速可在练习中调整。</p></div><button class="button primary" data-action="book-all">开始全册练习</button></div><div class="notice">目录参考：${esc(LOCAL_TEXTBOOK.referenceTitle)}。下面内容为本地自编练习，题目已内置 GA 美式发音音频；口语识别的文本匹配率不等同于专业发音评分。</div>${groups.map(unit=>`<section class="book-unit"><h2>${esc(unit)}</h2><div class="chapter-grid">${LOCAL_TEXTBOOK.sections.filter(section=>section.unit===unit).map(section=>{const rows=book.sentences.filter(s=>s.section===section.id),done=rows.filter(s=>state.sentenceStatus[s.id]==='mastered').length;return `<button class="chapter-card" data-action="book-lesson" data-id="${section.id}"><span class="chapter-number">${String(LOCAL_TEXTBOOK.sections.indexOf(section)+1).padStart(2,'0')}</span><strong>${esc(section.title)}</strong><span class="chapter-progress">${done} / ${rows.length} 已掌握 ${icon('arrow')}</span></button>`;}).join('')}</div></section>`).join('')}`;
