    if(lesson.mode==='typing')stage=`<span class="exercise-label">照着原文输入 · 正确与错误会逐字标记</span><div id="typing-target" class="typing-target" aria-label="英文原文">${esc(text)}</div><p class="lesson-chinese">${esc(translation)}</p><div id="typing-metrics" class="typing-metrics">准确率 — · 速度 0 WPM</div>`;
    if(lesson.mode==='listen')stage=`<span class="exercise-label">让耳朵先熟悉这句话</span><div class="lesson-english">${lesson.hideOriginal?'<span class="hidden-original">原文已隐藏 · 点击下方可显示</span>':esc(text)}</div><p class="lesson-chinese">${lesson.revealed?esc(translation):'先听一遍，再试着理解。'}</p><div class="lesson-controls"><button class="button small" data-action="toggle-original">${lesson.hideOriginal?'显示':'隐藏'}原文</button><button class="button small" data-action="reveal">显示中文</button><label class="listen-choice">重复 <select id="listen-repeat">${[1,2,3,5].map(n=>`<option value="${n}" ${lesson.repeat===n?'selected':''}>${n} 次</option>`).join('')}</select></label><label class="listen-choice"><input type="checkbox" id="listen-auto" ${lesson.autoNext?'checked':''}> 自动下一句</label></div><p id="listen-status" class="hint">本项完整播放 ${lesson.listened||0} 次。${lesson.playing?'正在播放…':''}</p>`;
