    const active=lesson,generation=mediaGeneration;recognition=new Constructor();recognition.lang=FrogPractice.speechProfile.locale;recognition.continuous=false;recognition.interimResults=false;
    active.recognizing=true;active.voiceMessage='正在识别，请朗读上面的英文。';active.transcript='';active.voiceResult=null;renderLesson();
