  async function ollama(path,body) {
    if(window.FrogMobile.isMobile())throw new Error('手机端尚未连接本地 AI。请在运行 Ollama 的电脑上使用 AI 功能；手机上的课程和背词可以继续使用。');
    const response=await fetch(`http://127.0.0.1:11434${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(90000)});
    if(!response.ok)throw new Error(`本地模型返回 ${response.status}。请确认模型已下载，且 Ollama 已允许此页面连接。`);
    return response.json();
  }
  async function connectAI() {
    const model=$('#model-name')?.value.trim()||state.settings.model||'gemma3:1b';
    if(!/^[a-zA-Z0-9][a-zA-Z0-9:._/\-]{0,149}$/.test(model))throw new Error('请输入有效的模型名称。');
    const data=await ollama('/api/tags');
    if(!data.models?.some(m=>m.name===model||m.name===`${model}:latest`))throw new Error(`本机尚未安装 ${model}，请先在 Ollama 中下载此模型。`);
    change(s=>s.settings.model=model,false);aiConnected=true;render();toast('已连接本机模型，可以开始对话');
  }
  async function sendChat(text) {
    if(aiBusy)return;
    if(!state.settings.model)throw new Error('请先在右侧检查本地模型连接。');
    aiBusy=true;
    change(s=>s.chat.push({role:'user',content:text}),false);render();
    try {
      const data=await ollama('/api/chat',{model:state.settings.model,stream:false,messages:[{role:'system',content:`You are a friendly English tutor. Topic: ${selectedTopic}. Respond in simple English. Correct at most one language mistake gently, with a short Chinese explanation if useful. Ask one follow-up question. Keep your response under 120 words.`},...state.chat.slice(-20)]});
      if(!data.message?.content)throw new Error('模型没有返回文字，请检查模型运行状态。');
      change(s=>s.chat.push({role:'assistant',content:data.message.content.slice(0,30000)}),false);aiConnected=true;
    } catch(error) {throw new Error(error instanceof TypeError?'无法连接本机 Ollama。请查看设置中的启动说明；浏览器可能需要允许本地网络访问。':error.message);}
    finally {aiBusy=false;if(route==='chat'){render();const el=$('#chat-messages');if(el)el.scrollTop=el.scrollHeight;}}
  }
