  function readableEmbeddedScript(source) {
    // Data catalogs also contain very long JSON lines. Format only complete
    // JSON assignments; leave application code and every string value intact.
    const assignment=source.match(/^((?:\s|\/\*[\s\S]*?\*\/)*window\.[A-Z_]+\s*=\s*)([\s\S]+?)(;\s*)$/);
    if(assignment){
      try{source=assignment[1]+JSON.stringify(JSON.parse(assignment[2]),null,1)+assignment[3];}catch{}
    }
    // Long base64 lines can exhaust the browser's textarea layout engine.
    // JavaScript line continuations keep every decoded byte unchanged.
    return source.replace(/(["'])((?:data:[^"',\r\n]+,)?[A-Za-z0-9+/=]{4096,})\1/g,(_,quote,data)=>quote+data.match(/.{1,2048}/g).join(String.fromCharCode(92,10))+quote);
  }
  // Pack binary bytes into safe BMP characters. A full base64 HTML archive can
  // exceed Chromium's maximum string length even though each asset is valid.
  // Fourteen bits per character keeps download and the existing source editor
  // within that limit, without changing a single decoded media byte.
  function packedExportLiteral(base64) {
    const bytes=atob(base64),chars=new Uint16Array(Math.ceil(bytes.length*8/14)),parts=[];let bits=0,value=0,next=0;
    for(let i=0;i<bytes.length;i++){
      value=(value<<8)|bytes.charCodeAt(i);bits+=8;
      if(bits>=14){bits-=14;chars[next++]=0x4e00+((value>>>bits)&0x3fff);value&=(1<<bits)-1;}
    }
    if(bits)chars[next++]=0x4e00+((value<<(14-bits))&0x3fff);
    for(let i=0;i<next;i+=2048)parts.push(String.fromCharCode(...chars.subarray(i,Math.min(i+2048,next))));
    return {literal:'"'+parts.join(String.fromCharCode(92,10))+'"',bytes:bytes.length};
  }
  function packedExportValue(value,dataURL=false) {
    const comma=dataURL?value.indexOf(','):-1,mime=dataURL?value.slice(5,value.indexOf(';')):'';
    const packed=packedExportLiteral(dataURL?value.slice(comma+1):value);
    return (dataURL?JSON.stringify('data:'+mime+';base64,')+'+':'')+`FrogUnpackMedia(${packed.literal},${packed.bytes})`;
  }
  function packedExportMap(name,values,dataURL=false) {
    return `window.${name}={};\n`+Object.entries(values).map(([key,value])=>`window.${name}[${JSON.stringify(key)}]=${packedExportValue(value,dataURL)};`).join('\n');
  }
  function packedExportRuntime() {
    return `window.FrogUnpackMedia=function(source,length){
      const bytes=new Uint8Array(length);let bits=0,value=0,next=0;
      for(let i=0;i<source.length&&next<length;i++){
        value=(value<<14)|(source.charCodeAt(i)-0x4e00);bits+=14;
        while(bits>=8&&next<length){bits-=8;bytes[next++]=(value>>>bits)&255;}
        value&=(1<<bits)-1;
      }
      if(next!==length)throw new Error('Offline media is incomplete.');
      let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
      return btoa(binary);
    };`;
  }
